481	/**
482	 * Reads `default.json`, writes it to `local.json`, and returns the parsed entries.
483	 * Called when `local.json` is absent.
484	 */
485	async function _initializeLocalFromDefault(): Promise<ModelEntry[]> {
486	  let defaultParsed: unknown;
487	  try {
488	    defaultParsed = await readJsonFile(defaultJsonPath());
489	  } catch (err) {
490	    throw new ApiError(
491	      'READ_ERROR',
492	      `Auto-initialization failed: could not read default.json: ${(err as Error).message}`
493	    );
494	  }
495	
496	  const result = ModelRegistrySchema.safeParse(defaultParsed);
497	  if (!result.success) {
498	    throw new ApiError(
499	      'VALIDATION_ERROR',
500	      `Auto-initialization failed: default.json schema validation error: ${result.error.message}`
501	    );
502	  }
503	
504	  await atomicWriteJson(localJsonPath(), result.data);
505	  process.stderr.write(
506	    `[model-registry] local.json not found — auto-initialized from default.json\n`
507	  );
508	  return result.data;
509	}

101	async function writeJson(filePath: string, data: unknown): Promise<void> {
102	  await writeFile(filePath, JSON.stringify(data, null, 2) + '\n', 'utf-8');
103	}
104	
105	async function seedDefaultJson(entries = DEFAULT_ENTRIES): Promise<void> {
106	  await writeJson(join(registryDir(), 'default.json'), entries);
107	}
108	
109	async function seedLocalJson(entries: unknown[]): Promise<void> {
110	  await writeJson(join(registryDir(), 'local.json'), entries);
111	}
112	
113	async function seedAssignmentsJson(data: unknown): Promise<void> {
114	  await writeJson(join(registryDir(), 'assignments.json'), data);
115	}
