 4	/**
 5	 * Writes JSON data to a file atomically using the write-to-temp-then-rename pattern.
 6	 *
 7	 * The process:
 8	 * 1. Write data to {filePath}.tmp.{pid}
 9	 * 2. Use fs.rename to atomically replace the target file (POSIX semantics)
10	 * 3. Clean up temp file on error
11	 *
12	 * This ensures that readers never see partial writes.
13	 *
14	 * @param filePath - Absolute path to the target file
15	 * @param data - Data to serialize as JSON
16	 * @throws Error if write or rename fails
17	 */
18	export async function atomicWriteJson(
19	  filePath: string,
20	  data: unknown
21	): Promise<void> {
22	  const pid = process.pid;
23	  const tempPath = `${filePath}.tmp.${pid}`;
24	
25	  try {
26	    // Ensure the parent directory exists
27	    const dir = dirname(filePath);
28	    await mkdir(dir, { recursive: true });
29	
30	    // Pretty-print JSON with 2-space indentation and trailing newline
31	    const json = JSON.stringify(data, null, 2) + '\n';
32	
33	    // Write to temp file
34	    await writeFile(tempPath, json, 'utf-8');
35	
36	    // Atomically rename temp file to target (POSIX atomic)
37	    await rename(tempPath, filePath);
38	  } catch (error) {
39	    // Clean up temp file if it exists
40	    try {
41	      await unlink(tempPath);
42	    } catch {
43	      // Ignore cleanup errors (temp file may not exist)
44	    }
45	
46	    // Re-throw original error
47	    throw new Error(
48	      `Failed to write JSON to ${filePath}: ${(error as Error).message}`
49	    );
50	  }
51	}

